INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2040,2004,0,0,0,0,0,0,'0',128,NULL,0,0,0,0,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Colophon',0,'','','','<p>This site is static HTML. Astro builds it from the JSON of tca-api-headless, served by TYPO3 14.3 from two page trees in one instance, and records every request it makes. The proofs show those recordings with the host replaced. No HTML is crawled and no text is copied.</p><p>Type: Schibsted Grotesk and Fragment Mono. The photographs and plates are generated images; Kettenblatt is invented.</p><p>This page has no German translation, on purpose: the German site runs in strict mode, so neither its menu nor its path lookup has it.</p>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2041,2004,0,0,0,0,0,0,'0',128,NULL,0,0,0,0,NULL,NULL,0,0,0,0,'default',1,NULL,'text',0,0,'','',0,'Source',0,'','','','<p>The site lives in the <a href=\"https://github.com/maikschneider/tca-api-headless/tree/main/website\" target=\"_blank\" title=\"The website directory on GitHub\">website directory</a> of the extension\'s repository, with its TYPO3 content as an SQL fixture.</p>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2045,2009,0,0,0,0,0,0,'0',128,NULL,0,0,0,0,NULL,NULL,0,0,0,0,'default',0,NULL,'textmedia',0,0,'','',0,'Content and rich text',0,'','','','<p>Seven content types of the core catalog arrive typed: text, text &amp; media, image, header, bullets, table and file links. Each has its own schema, discriminated by <code>CType</code>, and <code>bodytext</code> never contains HTML.</p>',0,1,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2046,2009,0,0,0,0,0,0,'0',128,NULL,0,0,0,0,NULL,NULL,0,0,0,0,'default',1,NULL,'text',0,0,'','',0,'Rich text as Portable Text',0,'','','','<p>Text from the rich text editor becomes <a href=\"https://www.portabletext.org/\" target=\"_blank\" title=\"Portable Text specification\">Portable Text</a>: blocks of spans with marks. <strong>Strong</strong>, <em>emphasis</em>, <u>underline</u>, <s>strike-through</s> and <code>code</code> are decorators; links are annotations.</p><h3>Headings, quotes and lists</h3><blockquote>A quote stays a block, with the style blockquote.</blockquote><ul><li>Lists nest<ul><li>with a level per depth</li></ul></li><li>and keep their type.</li></ul><p>Other markup is reduced to its text. Scripts and styles are dropped.</p>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
