INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2052,2009,0,0,0,0,0,0,'0',896,NULL,0,0,0,0,NULL,NULL,0,0,0,0,'default',1,NULL,'text',0,0,'','',0,'Types outside the catalog',0,'','','','<p>Other content types are left out, unless the site lists them in <code>fallbackCTypes</code>. Then they arrive with <code>uid</code>, <code>CType</code> and <code>header</code> only, typed as <code>HeadlessContentFallbackRead</code>. Kettenblatt allows <code>html</code>; the map card on its Visit page below is one.</p>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
