INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2100,2000,0,0,0,0,0,0,'0',256,NULL,0,1,2000,2000,NULL,NULL,0,0,0,0,'default',0,'','textmedia',0,0,'','',0,'Diese Seite ist eine TYPO3-Seite.',0,'','','','<p>Jeder Satz hier wurde in einem TYPO3-Seitenbaum geschrieben und von <strong>tca-api-headless</strong> als JSON ausgeliefert: zusammengesetzte Seiten, typisierte Inhaltselemente, Navigation und SEO-Metadaten für jedes Frontend. Jeder Abzug zeigt Anfrage, JSON und TypeScript-Typ hinter einem Abschnitt.</p><pre><code>composer require maikschneider/tca-api-headless:dev-main \\\n  \"maikschneider/tca-api:dev-release/2.4.0 as 2.4.0\"</code></pre>',0,1,NULL,NULL,0,0,0,2,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2101,2000,0,0,0,0,0,0,'0',256,NULL,0,1,2001,2001,NULL,NULL,0,0,0,0,'default',1,'','text',0,0,'','',0,'Redakteure bleiben in TYPO3',0,'','','','<p>Seitenbaum, Backend-Layouts, Inhaltselemente und Übersetzungen funktionieren so, wie Redakteure sie kennen. Im Backend ändert sich nichts: Das Frontend bekommt die Seite so, wie sie zusammengestellt wurde, als Daten statt als HTML.</p><p>Los geht es mit dem <a href=\"t3://page?uid=2001\">Schnellstart</a>, oder dieselbe API rendert die <a href=\"t3://page?uid=3000\" title=\"Eine erfundene Fahrradwerkstatt\">Muster-Site Kettenblatt</a>.</p>',0,0,NULL,NULL,0,0,0,2,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2102,2000,0,0,0,0,0,0,'0',256,NULL,0,1,2002,2002,NULL,NULL,0,0,0,0,'default',2,'','table',0,0,'','',0,'Was eine Antwort enthält',0,'','','','Feld|Was das Frontend bekommt\nregions|Inhaltselemente, gruppiert nach den Spalten-Identifiern des Backend-Layouts\nbodytext|Portable Text, Listeneinträge oder Tabellenzeilen, je nach Inhaltstyp\nheader_link|Ein Link-Objekt mit href, target und title\nmeta|Robots, eine kanonische URL in der Anfragesprache und eine schema.org-WebPage\nog_image|Eine absolute URL zum verarbeiteten Social-Media-Bild\nnavigation|Ein Menübaum mit absoluten URLs, begrenzt durch eine Tiefe\n?path=|Die Seiten-uid hinter einem URL-Pfad, in der Anfragesprache',0,0,NULL,NULL,0,0,0,2,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,1,0,NULL,0,'','','',0,0);
