INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2116,2001,0,0,0,0,0,0,'0',256,NULL,0,1,2016,2016,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Paket installieren',0,'','','','<pre><code>composer require maikschneider/tca-api-headless:dev-main \\\n  \"maikschneider/tca-api:dev-release/2.4.0 as 2.4.0\"</code></pre><p>Es bringt <a href=\"https://github.com/maikschneider/tca-api\" target=\"_blank\" title=\"TCA API auf GitHub\">TCA API</a> 2.4 oder neuer mit und läuft auf TYPO3 13.4 und 14.3. Beide sind in Entwicklung: bis zu ihren stabilen Releases gelten die expliziten Constraints oben. Für die SEO-Felder der Seiten EXT:seo (<code>typo3/cms-seo</code>) installieren.</p>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2117,2001,0,0,0,0,0,0,'0',384,NULL,0,1,2017,2017,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Site-Set hinzufügen',0,'','','','<p>Das Set kommt in jede Site, die Headless-Seiten ausliefern soll; es bringt das Set von TCA API mit. Sites ohne das Set liefern keine Ressourcen der Erweiterung. Das ist die <code>config.yaml</code> der Site, die Sie gerade lesen:</p><pre><code>dependencies:\n  - maikschneider/tca-api-headless</code></pre><p>Ein paar Site-Settings ändern die Vorgaben. Die <code>settings.yaml</code> dieser Site:</p><pre><code>tca_api_headless:\n  navigation:\n    depth: 2\n    maxDepth: 4\n  fallbackCTypes: []</code></pre>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2118,2001,0,0,0,0,0,0,'0',512,NULL,0,1,2018,2018,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Einen Pfad nachschlagen',0,'','','','<p>Ein Frontend kennt die URL. Das Nachschlagen macht aus ihrem Pfad die <code>uid</code> der Seite. Der Pfad gilt relativ zur Basis der Sprache:</p><pre><code>curl -H \'Accept: application/ld+json\' \'https://example.org/de/_api/headless_pages?path=/schnellstart\'</code></pre>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2119,2001,0,0,0,0,0,0,'0',640,NULL,0,1,2019,2019,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Die Seite anfragen',0,'','','','<p>Die Seite bringt ihre SEO-Felder, ein <code>meta</code>-Objekt für den Head und ihre Inhaltselemente, gruppiert nach Region:</p><pre><code>curl -H \'Accept: application/ld+json\' \'https://example.org/de/_api/headless_pages/2001\'</code></pre>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2120,2002,0,0,0,0,0,0,'0',128,NULL,0,1,2020,2020,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Funktionen',0,'','','','<p>Sechs Teile der API, jeder auf einer eigenen Seite. Jede Seite zeigt ihre Inhalte neben der Antwort, aus der sie stammen, und ein Stück <a href=\"t3://page?uid=2016\">Kettenblatt</a>, einer erfundenen Fahrradwerkstatt, gerendert von derselben API.</p>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
