INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2145,2009,0,0,0,0,0,0,'0',128,NULL,0,1,2045,2045,NULL,NULL,0,0,0,0,'default',0,NULL,'textmedia',0,0,'','',0,'Inhalte und Rich Text',0,'','','','<p>Sieben Inhaltstypen des Core-Katalogs kommen typisiert an: Text, Text &amp; Medien, Bild, Überschrift, Aufzählung, Tabelle und Dateilinks. Jeder hat sein eigenes Schema, unterschieden nach <code>CType</code>, und <code>bodytext</code> enthält nie HTML.</p>',0,1,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2146,2009,0,0,0,0,0,0,'0',128,NULL,0,1,2046,2046,NULL,NULL,0,0,0,0,'default',1,NULL,'text',0,0,'','',0,'Rich Text als Portable Text',0,'','','','<p>Text aus dem Rich-Text-Editor wird zu <a href=\"https://www.portabletext.org/\" target=\"_blank\" title=\"Spezifikation von Portable Text\">Portable Text</a>: Blöcke aus Spans mit Marks. <strong>Fett</strong>, <em>kursiv</em>, <u>unterstrichen</u>, <s>durchgestrichen</s> und <code>code</code> sind Decorators; Links sind Annotationen.</p><h3>Überschriften, Zitate und Listen</h3><blockquote>Ein Zitat bleibt ein Block, mit dem Stil blockquote.</blockquote><ul><li>Listen verschachteln sich<ul><li>mit einer Ebene pro Tiefe</li></ul></li><li>und behalten ihren Typ.</li></ul><p>Anderes Markup wird auf seinen Text reduziert. Scripts und Styles fallen weg.</p>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
