INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2190,2000,0,0,0,0,0,0,'0',128,NULL,0,1,2090,2090,NULL,NULL,0,0,0,0,'default',3,NULL,'text',0,0,'','',0,'Von composer zur ersten Antwort',0,'','','','<ol><li>Paket installieren: <code>composer require maikschneider/tca-api-headless:dev-main &quot;maikschneider/tca-api:dev-release/2.4.0 as 2.4.0&quot;</code></li><li>Das Site-Set <code>maikschneider/tca-api-headless</code> bei den Abhängigkeiten in der <code>config.yaml</code> der Site eintragen.</li><li>Den Spalten des Backend-Layouts Identifier wie <code>main</code> geben. Sie werden zu den Regionsnamen.</li><li>Eine Seite anfragen: <code>curl https://example.org/_api/headless_pages/1</code></li><li>Das OpenAPI-Dokument der Site schreiben und Typen daraus generieren:</li></ol><pre><code>vendor/bin/typo3 tca-api:openapi main --output openapi.json\nbunx openapi-typescript openapi.json -o src/api/schema.d.ts</code></pre><p>tca-api-headless ist in Entwicklung. Es braucht TCA API 2.4 und TYPO3 13.4 oder 14.3.</p>',0,0,NULL,NULL,0,0,0,2,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
