INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2306,2013,0,0,0,0,0,0,'0',768,NULL,0,1,2206,2206,NULL,NULL,0,0,0,0,'default',1,NULL,'text',0,0,'','',0,'Links im Rich Text',0,'','','','<p>Im Rich Text sind Links <code>link</code>-Annotationen mit denselben Eigenschaften: <a href=\"t3://page?uid=2010\">die Navigationsseite</a>, <a href=\"t3://page?uid=3003\" target=\"_blank\">die Räder von Kettenblatt</a> in einem neuen Tab, <a href=\"t3://file?uid=2026\">eine Datei</a> und <a href=\"t3://page?uid=2004\">das Kolophon</a>.</p><p>Nur http, https, mailto und tel bleiben erhalten. Anker, Datensatzlinks und Seiten ohne die Sprache lösen sich nicht auf: ihr Text bleibt, ohne Link. Das Kolophon gibt es nur auf Englisch, darum hat dieser Absatz auf Deutsch dort keinen Link.</p>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2307,2013,0,0,0,0,0,0,'0',128,NULL,0,1,2207,2207,NULL,NULL,0,0,0,0,'default',2,NULL,'header',0,0,'','',0,'Kettenblatt: Besuch',0,'','t3://page?uid=3001','',NULL,0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2310,2014,0,0,0,0,0,0,'0',128,NULL,0,1,2210,2210,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Der Vertrag',0,'','','','<p>TCA API schreibt pro Site ein OpenAPI-Dokument, und tca-api-headless typisiert alles, was es hinzufügt: Regionen, jeden Inhaltstyp, Links, den Navigationsbaum und das Nachschlagen. Das ist das Dokument dieser Site, gelesen beim Bau dieser Seite:</p><pre><code>GET /de/_api/openapi.json</code></pre>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2311,2014,0,0,0,0,0,0,'0',256,NULL,0,1,2211,2211,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Generiert, dann verglichen',0,'','','','<p>Diese Site generiert ihre TypeScript-Deklarationen mit openapi-typescript aus diesem Dokument, und ihre CI schlägt fehl, wenn beide auseinanderlaufen. Jeder Abzug auf dieser Site zeigt den Typ seines Elements, ausgeschnitten aus diesen Deklarationen.</p><pre><code>bunx openapi-typescript openapi.json -o src/api/schema.d.ts</code></pre><p>Das CLI schreibt dasselbe Dokument ohne Webanfrage:</p><pre><code>vendor/bin/typo3 tca-api:openapi website --output openapi.json</code></pre>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2312,2014,0,0,0,0,0,0,'0',384,NULL,0,1,2212,2212,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Ein Dokument pro Site',0,'','','','<p>Das Dokument gehört zu seiner Site. Kettenblatt erlaubt den Fallback-Typ <code>html</code>, darum hat nur sein Dokument <code>HeadlessContentFallbackRead</code>, und sein Frontend braucht eigene Typen:</p><pre><code>GET https://kettenblatt.example/de/_api/openapi.json</code></pre>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2320,2001,0,0,0,0,0,0,'0',768,NULL,0,1,2220,2220,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Typen generieren',0,'','','','<p>Das OpenAPI-Dokument der Site beschreibt jede Antwort. TypeScript daraus generieren und in der CI vergleichen:</p><pre><code>curl -o openapi.json \'https://example.org/_api/openapi.json\'\nbunx openapi-typescript openapi.json -o src/api/schema.d.ts</code></pre><p>Inhaltselemente lassen sich dann über <code>CType</code> eingrenzen:</p><pre><code>import type { components } from \'./api/schema\';\n\ntype Page = components[\'schemas\'][\'HeadlessPagesRead\'];\nconst base = \'https://example.org/de\';\nconst headers = { Accept: \'application/ld+json\' };\n\nconst lookup = await (await fetch(`${base}/_api/headless_pages?path=/schnellstart`, { headers })).json();\nconst page: Page = await (await fetch(`${base}/_api/headless_pages/${lookup[\'hydra:member\'][0].uid}`, { headers })).json();\n\nfor (const content of page.regions.aside ?? []) {\n  if (content.CType === \'table\') console.log(content.bodytext?.body); // string[][]\n}</code></pre>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2330,2015,0,0,0,0,0,0,'0',128,NULL,0,1,2230,2230,NULL,NULL,0,0,0,0,'default',0,NULL,'text',0,0,'','',0,'Erweiterungen',0,'','','','<p>tca-api-headless ist eine der Open-Source-Erweiterungen für TYPO3 von Maik Schneider. Das sind weitere, jede beschrieben mit einer Zeile aus ihrem README. Die Überschrift öffnet das Repository auf GitHub.</p>',0,0,NULL,NULL,0,0,0,1,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
